"""ORD_LINE renumbering migration."""

from decimal import Decimal
from typing import Any


def _order_id(row: dict[str, Any]) -> str:
    """Return ORD_ID using the legacy empty-string default."""
    return str(row.get("ORD_ID", ""))


def _line_number(row: dict[str, Any]) -> Decimal:
    """Return LINE_NO as a numeric value, treating a missing value as blank."""
    value = row.get("LINE_NO", "")
    if value == "":
        return Decimal(0)
    return Decimal(str(value))


def renumber(lines: list[dict]) -> list[dict]:
    """Remove soft-deleted rows and assign contiguous LINE_NO values per order."""
    surviving = [
        dict(row)
        for row in lines
        if row.get("DEL_FLG", "") != "Y"
    ]

    surviving.sort(key=lambda row: (_order_id(row), _line_number(row)))

    result: list[dict] = []
    current_order: str | None = None
    next_line_number = 0

    for row in surviving:
        order = _order_id(row)
        if order != current_order:
            current_order = order
            next_line_number = 1
        else:
            next_line_number += 1

        row["LINE_NO"] = next_line_number
        result.append(row)

    return result
